<template>
    <div class="cardBox">
        <p class="cardTitle">青少年脊柱专项风险评估</p>
        <!-- 青少年脊柱发育指数 -->
        <div class="cardItem">
            <p class="cardTop">
                <img src="../../assets/image/young/youngIcon1.png" alt="" />
                <span>青少年脊柱发育指数</span>
            </p>
            <p class="cardScore">
                <span>
                    <img :src="imgUrl[youthSpineDetail.youthStatus]" />
                    <b :style="{ color: colorLevels[youthSpineDetail.youthStatus] }">{{youthIndex}}</b>
                    <i> 分</i>
                </span>
                <span :style="{ background: colorLevels[youthSpineDetail.youthStatus] }">{{resultStatus[0][youthSpineDetail.youthStatus]}}</span>
