            <processBar :nums="[0, 11, 21, 31, 40]" :currentNum="youthIndex ? youthIndex : 0.1" :pWidth="1" :isPure="1"> </processBar>
            <p class="tips">{{errorResultArray[0][youthSpineDetail.youthStatus]}}</p>
        </div>

        <!-- 学习姿势负荷指数 -->
        <div class="cardItem">
