            <p class="cardScore">
                <span>
                    <img :src="imgUrl[youthSpineDetail.balanceStatus]" />
                    <b :style="{ color: colorLevels[youthSpineDetail.balanceStatus] }">{{balanceScore}}</b>
                    <i> 分</i>
                </span>
                <span :style="{ background: colorLevels[youthSpineDetail.balanceStatus]}">{{resultStatus[2][youthSpineDetail.balanceStatus]}}</span>
            </p>
            <processBar :nums="[0, 16, 26, 35, 45]" :currentNum="balanceScore ? balanceScore : 0.1 " :pWidth="1" :isPure="1"> </processBar>
            <p class="tips">{{errorResultArray[2][youthSpineDetail.balanceStatus]}}</p>
        </div>

        <!-- 生长期疼痛预警指数 -->
        <div class="cardItem">
